import { countTokens } from "./meter.mjs";

export const SMALL_MODEL = "sim-small";
export const LEAD_MODEL = "sim-lead";

export function routeModel(task) {
  if (task.kind === "classify") return SMALL_MODEL;
  return LEAD_MODEL;
}

export function compressPrompt(text) {
  return String(text).replace(/\s+/g, " ").trim();
}

export function compressedTokens(text) {
  return countTokens(compressPrompt(text));
}

import assert from "node:assert/strict";
import test from "node:test";
import { countTokens } from "../src/token/meter.mjs";
import { LEAD_MODEL, SMALL_MODEL, compressedTokens, routeModel } from "../src/token/router.mjs";

test("a classify fixture uses the small sim model and a tighter prompt", () => {
  const choice = routeModel({ kind: "classify", text: "label this note" });
  assert.equal(choice, SMALL_MODEL);
  assert.equal(routeModel({ kind: "plan" }), LEAD_MODEL);
  assert.doesNotMatch(choice, /openai/i);
  assert.doesNotMatch(LEAD_MODEL, /openai/i);

  const padded = "  classify   this    note   ";
  assert.ok(compressedTokens(padded) < countTokens(padded));
});

import { writeFileSync } from "node:fs";

export function countTokens(text) {
  const size = String(text ?? "").length;
  return Math.max(1, Math.ceil(size / 4));
}

export function baselineRecord(task) {
  return {
    task: task.id,
    tokens: countTokens(task.prompt),
    success: task.success === true,
  };
}

export function writeBaseline(file, task) {
  const record = baselineRecord(task);
  writeFileSync(file, `${JSON.stringify(record)}\n`);
  return record;
}

/**
 * OPT-26 bench. Runs every improvement against its old behaviour on local inputs
 * and prints real before/after numbers. node src/opt/bench.mjs [--json]
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { performance } from "node:perf_hooks";
import { countTokens } from "../token/meter.mjs";
import { compressPrompt, routeModel } from "../token/router.mjs";
import { createSummaryCache } from "../token/summary-cache.mjs";
import { createForeman } from "../studio/task-graph.mjs";
import { simPen } from "../studio/planner.mjs";
import { checkMessage, loadProtocolUncached, validate, protocolDir } from "../studio/protocol.mjs";
import * as T from "./token-lab.mjs";
import * as H from "./handoff.mjs";
import * as R from "./relay.mjs";
import * as R2 from "./round2.mjs";
import { createHash } from "node:crypto";

const root = join(dirname(fileURLToPath(import.meta.url)), "../../../..");
const read = (p) => readFileSync(join(root, p), "utf8");
const buildLog = read("docs/v2/BUILD-LOG.md");
const memory = read("docs/v2/v2-memory.jsonl");
const memRows = memory.trim().split("\n");
const memJson = JSON.stringify(JSON.parse(memRows[0]), null, 2);
const fixture = "Describe the studio wall in one line.";
const tok = countTokens;
const rows = [];
const add = (n, name, metric, before, after, lowerIsBetter = true) => rows.push({ n, name, metric, before, after, lowerIsBetter });

export async function runBench() {
  rows.length = 0;
  // Token lab. "before" is today's compressPrompt (whitespace fold), the existing V2 pass.
  const logTwice = memRows.slice(0, 40).join("\n") + "\n" + memRows.slice(0, 40).join("\n");
  add(1, "dedupe-lines", "tokens (memory rows sent twice)", tok(compressPrompt(logTwice)), tok(T.dedupeLines(logTwice)));
  const ask = "Please could you kindly review the board. I would like you to just check every lane in order to find the blocker. It is important to note that basically nothing merges without the gate.";
  add(2, "cut-filler", "tokens (polite task ask)", tok(compressPrompt(ask)), tok(compressPrompt(T.cutFiller(ask))));
  add(3, "compact-json", "tokens (pretty JSON memory row)", tok(memJson), tok(T.compactJson(memJson)));
  add(4, "ref-legend", "tokens (BUILD-LOG with repeated URLs/SHAs)", tok(buildLog), tok(T.refLegend(buildLog)));
  // 5/6 prompt cache over a 100-task mix with 20 distinct asks, repeats vary in case/space.
  const asks = Array.from({ length: 100 }, (_, i) => { const b = `summarize lane ${i % 20} status`; return i % 3 === 0 ? b.toUpperCase() : i % 3 === 1 ? `  ${b}  ` : b; });
  const model = async () => "ok";
  let calls = 0; for (const a of asks) { calls++; await model(a); }
  const exact = T.createPromptCache({ normalize: false }); for (const a of asks) await exact.get(a, model);
  add(5, "exact-prompt-cache", "model calls per 100 tasks", calls, exact.stats().misses);
  const norm = T.createPromptCache({ normalize: true }); for (const a of asks) await norm.get(a, model);
  add(6, "normalized-cache-key", "model calls per 100 tasks", exact.stats().misses, norm.stats().misses);
  add(7, "fit-budget", "max context tokens (budget 512, memory file)", tok(compressPrompt(memory)), tok(T.fitBudget(memory, 512)));
  // 8 routing: 50 tasks, 40 short "answer" asks, 10 long plans.
  const tasks = [...Array.from({ length: 40 }, () => ({ kind: "answer", prompt: memRows[1].slice(0, 400) })), ...Array.from({ length: 10 }, () => ({ kind: "plan", prompt: buildLog }))];
  const cost = (fn) => tasks.reduce((s, t) => s + T.computeUnits(fn(t), tok(t.prompt)), 0);
  add(8, "route-by-size", "compute units per 50 tasks", +cost(routeModel).toFixed(2), +cost((t) => T.routeBySize(t)).toFixed(2));
  // 9 summary repeat: 10 calls, summary grows by one line each time.
  const old = createSummaryCache(), neu = T.createDiffCache();
  let a = 0, b = 0, s = "";
  for (let i = 0; i < 10; i++) { s += memRows[i].slice(0, 120) + "\n"; a += old.context("p", memory, s).tokens; b += neu.context("p", memory, s).tokens; }
  add(9, "diff-only-summary", "tokens over 10 repeat calls", a, b);
  const toolOut = memRows.slice(0, 200).join("\n");
  add(10, "clip-tool-result", "tokens (200-line tool output)", tok(toolOut), tok(T.clipToolResult(toolOut)));
  add(11, "pack-context chain", "tokens (V2-051 fixture)", tok(fixture), tok(T.packContext(fixture)));
  add(11.1, "pack-context chain", "tokens (BUILD-LOG lossless)", tok(compressPrompt(buildLog)), tok(T.packContext(buildLog)));
  // Task graph and studio.
  const dag = [{ id: "a" }, { id: "b" }, { id: "c" }, { id: "d", dependsOn: ["a", "b"] }, { id: "e", dependsOn: ["b", "c"] }, { id: "f", dependsOn: ["d"] }, { id: "g", dependsOn: ["e"] }, { id: "h", dependsOn: ["f", "g"] }, { id: "i" }, { id: "j", dependsOn: ["i"] }];
  add(12, "parallel-waves", "sequential steps for 10-task DAG", dag.length, H.waves(dag).length);
  let ok1 = 0, ok3 = 0;
  for (let i = 0; i < 20; i++) {
    const flaky = () => { let n = 0; return async () => { if (n++ < (i % 3)) throw new Error("flake"); return 1; }; };
    try { await H.withRetry(flaky(), { attempts: 1 }); ok1++; } catch {}
    try { await H.withRetry(flaky(), { attempts: 3 }); ok3++; } catch {}
  }
  add(13, "capped-retry", "tasks finished of 20 flaky", ok1, ok3, false);
  const f1 = createForeman(); let errs = 0; f1.addTask({ id: "x" }); f1.start("x"); f1.complete("x"); try { f1.complete("x"); } catch { errs++; }
  const f2 = createForeman(); f2.addTask({ id: "x" }); f2.start("x"); const done = H.idempotentComplete(f2); let errs2 = 0; done("x"); try { done("x"); } catch { errs2++; }
  add(14, "idempotent-complete", "errors from duplicate done event", errs, errs2);
  const row = { type: "worker.event", taskId: "t1", name: "tool.read", detail: "x" };
  const t0 = performance.now(); for (let i = 0; i < 500; i++) { const { schema } = loadProtocolUncached(protocolDir()); validate(schema.messages[row.type], row); } const t1 = performance.now();
  checkMessage(row); const t2 = performance.now(); for (let i = 0; i < 500; i++) checkMessage(row); const t3 = performance.now();
  add(15, "memo-protocol-load", "ms per 500 message checks", +(t1 - t0).toFixed(2), +(t3 - t2).toFixed(2));
  const h = { from: "Gitbook", to: "Build", task: "GB-066", status: "approved", refs: ["/workspace/gitbook-cordnation/GB-066/GB-066.diff", "2344334e"], next: "gate and reply PASS/FAIL" };

/**
 * OPT round 2 (Rick's inventions R2-1..R2-9). R2-10 resonate-batch skipped (noise).
 * R2-2 key-hoist and R2-8 earth-return change the wire format: they are opt-in and
 * ship with their decode step (unhoist / earth.receive).
 */
import { createHash } from "node:crypto";
import { countTokens } from "../token/meter.mjs";
import { compressPrompt } from "../token/router.mjs";
import { dedupeLines, refLegend, expandLegend } from "./token-lab.mjs";

/** R2-1 prefix-legend (finishes OPT-04): legend for repeated path prefixes. Decode with expandPrefix. */
export function prefixLegend(text, { minLen = 12, minCount = 3, max = 9 } = {}) {
  const s = String(text);
  if (s.includes("§")) return s;
  const cnt = new Map();
  for (const w of s.match(/[\w.:@#-]+(?:\/[\w.:@#-]+)+\/?/g) ?? []) {
    const parts = w.split("/"); let p = "";
    for (let i = 0; i < parts.length - 1; i++) { p += parts[i] + "/"; if (p.length >= minLen) cnt.set(p, (cnt.get(p) ?? 0) + 1); }
  }
  const cand = [...cnt].filter(([, n]) => n >= minCount)
    .map(([p, n]) => [p, n * (p.length - 3) - (p.length + 4)]).filter(([, g]) => g > 0)
    .sort((a, b) => b[0].length - a[0].length);
  const picks = [];
  for (const [p] of cand) { if (!picks.find((q) => q.startsWith(p))) picks.push(p); if (picks.length >= max) break; }
  let out = s; const legend = [];
  picks.forEach((p, i) => { if (!out.includes(p)) return; out = out.split(p).join(`§${legend.length}`); legend.push(`§${legend.length}=${p}`); });
  return legend.length ? legend.join(" ") + "\n" + out : s;
}
export const expandPrefix = (t) => expandLegend(t);

/** R2-2 key-hoist (opt-in wire format): JSONL rows -> key list once per row shape + value arrays. */
export function keyHoist(rows) {
  const groups = new Map();
  rows.forEach((r, i) => {
    const o = typeof r === "string" ? JSON.parse(r) : r;
    const k = JSON.stringify(Object.keys(o));
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push([i, Object.values(o)]);
  });
  return JSON.stringify({ hoist: 1, g: [...groups].map(([k, v]) => ({ k: JSON.parse(k), r: v })) });
}
/** Decode step for keyHoist: returns minified JSON rows in original order. */
export function unhoist(s) {
  const doc = JSON.parse(s);
  if (doc?.hoist !== 1) throw new Error("not a key-hoist payload");
  const out = [];
  for (const g of doc.g) for (const [i, vals] of g.r) out[i] = JSON.stringify(Object.fromEntries(g.k.map((k, j) => [k, vals[j]])));
  return out;
}

/** R2-3 resonate-chain (finishes OPT-11): try every order/subset of passes, keep the smallest verified output. */
export const CHAIN_PASSES = { dedupe: dedupeLines, ws: (t) => compressPrompt(t), prefix: (t) => prefixLegend(t), ref: (t) => refLegend(t) };
const perms = (a) => (a.length <= 1 ? [a] : a.flatMap((x, i) => perms([...a.slice(0, i), ...a.slice(i + 1)]).map((p) => [x, ...p])));
/** Default check: decoded output equals the deduped+whitespace-folded input (same contract as packContext). */
export const chainVerifier = (text) => {
  const ok = new Set([compressPrompt(dedupeLines(text)), compressPrompt(text), dedupeLines(compressPrompt(text))]);
  return (out) => ok.has(compressPrompt(expandLegend(out)));
};
export function resonateChain(text, verify = chainVerifier(text), passes = CHAIN_PASSES) {
  const names = Object.keys(passes); let best = { out: String(text), chain: [] };
  for (let m = 1; m < 1 << names.length; m++) {
    const sub = names.filter((_, i) => (m >> i) & 1);
    for (const ch of perms(sub)) {
      const out = ch.reduce((t, n) => passes[n](t), String(text));
      if (countTokens(out) < countTokens(best.out) && verify(out)) best = { out, chain: ch };
    }
  }
  return best;
}

/** R2-4 coincide: act only when every independent check agrees (default 3 of 3). */
export function coincide(checks, need = checks.length) {
  const yes = checks.filter(Boolean).length;
  return { act: yes >= need, yes, of: checks.length };
}

/** R2-5 phase: stagger worker i to start on tick (i mod K). */
export const phaseStarts = (n, K = 4) => Array.from({ length: n }, (_, i) => i % K);
export const peakStarts = (starts) => Math.max(0, ...Object.values(starts.reduce((m, t) => ((m[t] = (m[t] ?? 0) + 1), m), {})));

/** R2-6 valve: append-only log; rewriting an existing index is refused. */
export function valveLog() {
  const lines = [];
  return {
    append: (l) => lines.push(l),
    write: (i, l) => { if (i !== lines.length) return false; lines.push(l); return true; },
    lines: () => lines.slice(),
  };
}

/** R2-7 bifilar: every open must be paired with a close; returns ids left open. */
export function bifilar(events) {
  const open = new Map();
  for (const [t, id] of events) { if (t === "open") open.set(id, (open.get(id) ?? 0) + 1); else if (open.has(id)) { const n = open.get(id) - 1; n ? open.set(id, n) : open.delete(id); } }
  return [...open.keys()];
}

/** R2-8 earth-return (opt-in wire format): body stored once, chain passes a 16-hex ref. */
export function createEarthStore() {
  const store = new Map();
  return {
    send(body) { const ref = createHash("sha256").update(String(body)).digest("hex").slice(0, 16); store.set(ref, String(body)); return { ref }; },
    receive(msg) {
      if (msg && typeof msg.ref === "string") { if (!store.has(msg.ref)) throw new Error(`earth-return: unknown ref ${msg.ref}`); return store.get(msg.ref); }
      return typeof msg === "string" ? msg : msg?.body;
    },
    size: () => store.size,
  };
}

/** R2-9 tuned-clip: keep lines matching the query (then head lines) up to maxLines. */
export function tunedClip(text, query, { maxLines = 40 } = {}) {
  const lines = String(text).split("\n");
  if (lines.length <= maxLines) return String(text);
  const q = String(query).toLowerCase();
  const hit = []; lines.forEach((l, i) => { if (q && l.toLowerCase().includes(q)) hit.push(i); });
  const keep = new Set(hit.slice(0, maxLines - 5));
  for (let i = 0; keep.size < maxLines && i < lines.length; i++) keep.add(i);
  return [...keep].sort((a, b) => a - b).map((i) => lines[i]).join("\n") + `\n[${lines.length - keep.size} lines clipped]`;
}

}
export function computeUnits(model, tokens) {
  return (model === SMALL_MODEL ? 1 : 10) * tokens / 1000;
}

/** OPT-09: on a repeat call send only the summary diff, not previous+diff. */
export function createDiffCache() {
  const summaries = new Map();
  return {
    context(key, fullText, summary) {
      const previous = summaries.get(key);
      summaries.set(key, summary);
      if (previous === undefined) return { hit: false, tokens: countTokens(fullText) };
      if (summary === previous) return { hit: true, tokens: 0 };
      const diff = summary.startsWith(previous) ? summary.slice(previous.length) : summary;
      return { hit: true, tokens: countTokens(diff) };
    },
  };
}

/** OPT-10: clip a long tool result to head lines plus a count of what was cut. */
export function clipToolResult(text, { maxLines = 40 } = {}) {
  const lines = String(text).split("\n");
  if (lines.length <= maxLines) return String(text);
  return [...lines.slice(0, maxLines), `[${lines.length - maxLines} more lines clipped]`].join("\n");
}

/** OPT-11: chain of passes used by the token lab. Lossless ones first. */
export function packContext(text, { budget = Infinity } = {}) {
  const packed = refLegend(compressPrompt(cutFiller(dedupeLines(compactJson(text)))).replace(/ \n/g, "\n"));
  return Number.isFinite(budget) ? fitBudget(packed, budget) : packed;
}

import assert from "node:assert/strict";
import test from "node:test";
import * as T from "../src/opt/token-lab.mjs";
import { runBench } from "../src/opt/bench.mjs";
import { SMALL_MODEL, LEAD_MODEL } from "../src/token/router.mjs";

const bench = await runBench();
const row = (n) => bench.find((r) => r.n === n);
const gains = (n) => assert.ok(row(n).improved, `OPT-${n} did not improve: ${JSON.stringify(row(n))}`);

test("OPT-01 dedupe-lines keeps first copy and order", () => {
  assert.equal(T.dedupeLines("a\nb\na\n\nb\nc"), "a\nb\n\nc"); gains(1);
});
test("OPT-02 cut-filler removes filler, keeps the ask", () => {
  assert.equal(T.cutFiller("Please check the gate in order to merge."), "check the gate to merge."); gains(2);
});
test("OPT-03 compact-json is lossless", () => {
  const s = JSON.stringify({ a: [1, 2], b: { c: "d" } }, null, 2);
  assert.deepEqual(JSON.parse(T.compactJson(s)), JSON.parse(s)); assert.equal(T.compactJson("not json"), "not json"); gains(3);
});
test("OPT-04 ref-legend round-trips (gain not required: measured NO GAIN on BUILD-LOG)", () => {
  const s = "see /workspace/a/b/c/long.diff then /workspace/a/b/c/long.diff again";
  assert.ok(T.refLegend(s).length < s.length); assert.equal(T.expandLegend(T.refLegend(s)), s);
});
test("OPT-05 exact cache answers a repeat without a model call", async () => {
  const c = T.createPromptCache({ normalize: false }); let n = 0; const m = async () => ++n;
  await c.get("x", m); await c.get("x", m); await c.get("X", m); assert.equal(n, 2); gains(5);
});
test("OPT-06 normalized cache folds case and space", async () => {
  const c = T.createPromptCache(); let n = 0; const m = async () => ++n;
  await c.get("Lane  1", m); await c.get(" lane 1 ", m); assert.equal(n, 1); gains(6);
});
test("OPT-07 fit-budget never exceeds the budget", () => {
  const out = T.fitBudget("x".repeat(10000), 100); assert.ok(out.length <= 400); assert.equal(T.fitBudget("short", 100), "short"); gains(7);
});
test("OPT-08 route-by-size keeps plans on the lead model", () => {
  assert.equal(T.routeBySize({ kind: "plan", prompt: "a" }), LEAD_MODEL);
  assert.equal(T.routeBySize({ kind: "answer", prompt: "a" }), SMALL_MODEL); gains(8);
});
test("OPT-09 diff cache sends zero tokens for an unchanged summary", () => {
  const c = T.createDiffCache(); c.context("k", "full", "s"); assert.equal(c.context("k", "full", "s").tokens, 0); gains(9);
});
test("OPT-10 clip-tool-result keeps the head and says how much was cut", () => {
  const out = T.clipToolResult(Array.from({ length: 50 }, (_, i) => i).join("\n"), { maxLines: 5 });
  assert.match(out, /45 more lines clipped/); gains(10);
});
test("OPT-11 pack-context: V2-051 fixture unchanged, real log shrinks", () => {
  assert.equal(row(11).after, 10); gains(11.1);
});

import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync } from "node:fs";
import * as R2 from "../src/opt/round2.mjs";
import { runBench } from "../src/opt/bench.mjs";

const bench = await runBench();
const gains = (n) => { const r = bench.find((x) => x.n === n); assert.ok(r.improved, JSON.stringify(r)); };
const buildLog = readFileSync(new URL("../../../docs/v2/BUILD-LOG.md", import.meta.url), "utf8");
const memRows = readFileSync(new URL("../../../docs/v2/v2-memory.jsonl", import.meta.url), "utf8").trim().split("\n");

test("R2-1 prefix-legend round-trips exactly and saves tokens", () => {
  const p = R2.prefixLegend(buildLog); assert.equal(R2.expandPrefix(p), buildLog); assert.equal(R2.prefixLegend("a § b"), "a § b"); gains(27);
});
test("R2-2 key-hoist round-trip (opt-in decode)", () => {
  const rows = memRows.slice(0, 200).map((r) => JSON.stringify(JSON.parse(r)));
  assert.deepEqual(R2.unhoist(R2.keyHoist(rows)), rows);
  const mixed = [{ a: 1, b: "x" }, { c: [1, 2] }, { a: 2, b: "y" }, { "a,b": 3 }].map((o) => JSON.stringify(o));
  assert.deepEqual(R2.unhoist(R2.keyHoist(mixed)), mixed);
  assert.throws(() => R2.unhoist("[]")); gains(28);
});
test("R2-3 resonate-chain output verifies against dedupe+ws text", () => {
  const b = R2.resonateChain(buildLog); assert.ok(b.chain.length > 0); assert.ok(R2.chainVerifier(buildLog)(b.out)); gains(29);
});
test("R2-4 coincide refuses on 2 of 3", () => {
  assert.equal(R2.coincide([true, true, false]).act, false); assert.equal(R2.coincide([true, true, true]).act, true); gains(30);
});
test("R2-5 phase never exceeds ceil(n/K) per tick", () => {
  for (const [n, K] of [[12, 4], [13, 4], [5, 3]]) assert.ok(R2.peakStarts(R2.phaseStarts(n, K)) <= Math.ceil(n / K)); gains(31);
});
test("R2-6 valve refuses rewrites, allows append", () => {
  const v = R2.valveLog(); v.append("a"); assert.equal(v.write(0, "x"), false); assert.equal(v.write(5, "x"), false); assert.equal(v.write(1, "b"), true); assert.deepEqual(v.lines(), ["a", "b"]); gains(32);
});
test("R2-7 bifilar finds unmatched opens", () => {
  assert.deepEqual(R2.bifilar([["open", 1], ["open", 2], ["close", 1], ["close", 3]]), [2]);
  assert.deepEqual(R2.bifilar([["open", 1], ["open", 1], ["close", 1]]), [1]); gains(33);
});
test("R2-8 earth-return round-trip (opt-in decode)", () => {
  const e = R2.createEarthStore(); const m = e.send(buildLog); assert.match(m.ref, /^[0-9a-f]{16}$/);
  assert.equal(e.receive(JSON.parse(JSON.stringify(m))), buildLog); assert.equal(e.receive("plain"), "plain");

