node --input-type=module - << 'JS'
import { readFileSync } from "node:fs";
const countTokens = (text) => Math.max(1, Math.ceil(String(text ?? "").length / 4));
const oldCompress = (text) => String(text).replace(/\s+/g, " ").trim();

const HTML_COMMENT = /<!--[\s\S]*?-->/g;
const IMAGE = /!\[([^\]]*)\]\(([^)\n]*)\)/g;
const LINK = /\[([^\]]*)\]\(([^)\n]*)\)/g;
const FENCE_LANG = /^```[A-Za-z0-9_+-]+[ \t]*$/gm;
const BANG = /!{2,}/g;
const Q = /\?{2,}/g;

function compress(text, { punct = false } = {}) {
  let s = String(text).replace(HTML_COMMENT, " ");
  // protect fenced blocks: only drop language tag on the opener line
  s = s.replace(FENCE_LANG, "```");
  s = s.replace(IMAGE, "$1").replace(LINK, "$1");
  if (punct) s = s.replace(BANG, "!").replace(Q, "?");
  return s.replace(/\s+/g, " ").trim();
}

function report(path, punct=false) {
  const text = readFileSync(path, "utf8");
  const before = countTokens(oldCompress(text));
  const after = countTokens(compress(text, { punct }));
  const saved = before - after;
  const pct = (saved / before) * 100;
  console.log(`${punct?"PUNCT ":""}${path} before=${before} after=${after} saved=${saved} pct=${pct.toFixed(2)} chars ${text.length}->${compress(text,{punct}).length} oldChars=${oldCompress(text).length}`);
}
for (const p of [
